from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    For each parentheses group separated by spaces, returns the maximum nesting depth.
    """
    groups = paren_string.split()
    depths = []
    for group in groups:
        stack = []
        max_depth = 0
        for ch in group:
            if ch == '(': 
                stack.append(ch)
                if len(stack) > max_depth:
                    max_depth = len(stack)
            elif ch == ')':
                if stack:
                    stack.pop()
        # The stack should be empty for valid input, but just in case
        depths.append(max_depth)
    return depths
