from collections import Counter

def pairs_sum_to_zero(l):
    """
    pairs_sum_to_zero takes a list of integers as an input.
    It returns True if there exist two distinct elements in the list
    that sum to zero, otherwise False.
    """

    # Count occurrences of each number
    count = Counter(l)

    # For each number, check if its negation (that is not itself when number != 0) exists
    for num in count:
        if num == 0:
            # Need at least two zeros to form a pair (0+0=0)
            if count[0] >= 2:
                return True
        else:
            if -num in count:
                # Make sure it's a distinct element (if num == -num and only one occurrence, it's not valid)
                if num != -num or count[num] >= 2:
                    return True
    return False

