import string

def encode_shift(s: str) -> str:
    """
    Returns encoded string by shifting every letter by 5 positions forward in the alphabet.
    Non-alphabetic characters are left unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift within alphabet, wrap around using modulo 26
            shift = (ord(ch) - ord('a') + 5) % 26
            result.append(chr(shift + ord('a')))
        else:
            result.append(ch)
    return "".join(result)

def decode_shift(s: str) -> str:
    """
    Takes a string encoded with encode_shift and returns the decoded original string.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift back by 5 positions
            shift = (ord(ch) - ord('a') - 5) % 26
            if shift < 0:
                shift += 26
            result.append(chr(shift + ord('a')))
        else:
            result.append(ch)
    return "".join(result)
