import string

def encode(message):
    """
    Encodes the given message by swapping the case of all letters and replacing each vowel
    with the letter that is 2 places ahead in the English alphabet. Non-letters are ignored.
    """
    vowels = "aeiouAEIOU"
    result = []
    for c in message:
        if c.isalpha():  # Consider only letters
            if c.lower() in vowels:
                # Determine the base (lowercase) vowel
                base = c.lower()
                # Find the offset (0,1,2,3,4 for a,e,i,o,u)
                idx = 'aeiou'.index(base)
                new_ch = chr((ord('a') + idx + 2) % 26 + 97)
                # Use the case of the original character
                if c.isupper():
                    result.append(new_ch.upper())
                else:
                    result.append(new_ch)
            else:
                # For consonants, swap the case
                if c.isupper():
                    result.append(c.lower())
                else:
                    result.append(c.upper())
        else:
            # Non-letters are kept as is (problem only mentions letters, but this is safe)
            result.append(c)
    return ''.join(result)
