            if ',' in s:
                s = s.replace(',', '.')
            return float(s)
        except ValueError:
            raise ValueError(f"Invalid numeric string: {s}")

    fa = float(a) if isinstance(a, str) else a
    fb = float(b) if isinstance(b, str) else b

    # If both are numbers
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        if fa > fb:
