import math

def words_in_sentence(sentence: str) -> str:
    """
    Returns a string consisting of words in the original sentence whose lengths are prime numbers,
    preserving the original order. Words are separated by single spaces in the output.
    """
    # Helper function to check if a number is prime
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Split the sentence into words
    words = sentence.split()
    # Filter words by prime length
    primes_words = [w for w in words if is_prime(len(w))]
    # Join the selected words back into a string
    return " ".join(primes_words)
