def bf(planet1, planet2):
    """
    Returns a tuple of planet names whose orbits are between planet1 and planet2,
    sorted by proximity to the Sun (i.e., in order from innermost to outermost).
    If either planet name is invalid, returns an empty tuple.
    """
    # Define the order of the planets from closest to farthest from the Sun
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Check validity of input planet names (case-insensitive match)
    def is_valid(planet):
        return planet.strip().capitalize() in planets

    if not (is_valid(planet1) and is_valid(planet2)):
        return ()

    # Normalize inputs to corresponding indices in planets list
    try:
        idx1 = planets.index(planet1.strip().capitalize())
        idx2 = planets.index(planet2.strip().capitalize())
    except ValueError:
        # Should not occur, but handles accidental typo
        return ()

    # Normalize order: always have start < end
    if idx1 < idx2:
        start, end = idx1, idx2
    else:
        start, end = idx2, idx1

    # Return tuple of planets in between (exclusive of start and end)
    return tuple(planets[i] for i in range(start + 1, end))
